begin;
do $curate$ declare r jsonb; bid uuid; applied jsonb; begin
for r in select value from jsonb_array_elements('[{"name": "Manteca Critter Sitters", "category": "Pet Services", "city": "Manteca", "address": null, "phone": "(209) 539-1025", "website": "https://www.mantecacrittersitters.com/", "source_url": "https://www.mantecacrittersitters.com/", "duplicate_key": "mantecacrittersitters.com", "areas": ["Manteca"], "tags": ["pet sitting", "dog walking"], "description": "Advertises drop-in pet care and midday dog walks in Manteca, with pets staying in their own home. Call to confirm your address, animal needs, visit schedule, total quote and available dates. No boarding facility or visitable office established.", "note": "First-party homepage checked November 13, 2026 with fresh HTTP200: identity, public phone2095391025, advertised in-home drop-in care/dog walks and explicit Manteca service area. Other cities not established. Medication capability, licensing, insurance, bonding, quality and safety claims not independently validated. No availability, holiday hours or booking promised. No provider images, testimonials or third-party ratings reused. Source: https://www.mantecacrittersitters.com/"}, {"name": "Tyler\u2019s Pet Boarding", "category": "Pet Services", "city": "Lathrop", "address": null, "phone": null, "website": "https://www.tylerspetboarding.com/", "source_url": "https://www.tylerspetboarding.com/", "duplicate_key": "tylerspetboarding.com", "areas": ["Lathrop", "Manteca", "Tracy"], "tags": ["pet sitting", "pet boarding", "dog day care", "cat sitting"], "description": "Lathrop home-based provider advertising dog boarding/day care, house sitting, drop-in visits and cat care. Official service list names Lathrop, Manteca and Tracy; boarding and meet-and-greets are at the Lathrop home, while house sitting and visits are at the client\u2019s address. Site states smaller dogs only. Use the website request route to confirm fit, exact address, quote and dates; no public phone or visitor street address established.", "note": "First-party homepage checked November 13, 2026 with fresh HTTP200: identity, Lathrop base, advertised boarding/day care/house sitting/drop-in/cat care, smaller-dog restriction and individually named Lathrop/Manteca/Tracy service cities. Site also names Stockton/Modesto, outside this relaunch check. No Mountain House coverage established and no dog-walking tag inferred. Public website request route and business email tylerspetboarding@gmail.com observed; no request or message sent. Meet-and-greet is by appointment, not a booking. Background check, experience, medication capability, quality and safety claims not independently validated. No same-day reply, availability, price, holiday or cancellation guarantee adopted. No portfolio/review/photos reused. Source: https://www.tylerspetboarding.com/"}]'::jsonb) loop
 if exists(select 1 from public.businesses where lower(name)=lower(r->>'name') or website ilike '%'||(r->>'duplicate_key')||'%' or (r->>'phone' is not null and right(regexp_replace(coalesce(phone,''),'[^0-9]','','g'),10)=right(regexp_replace(r->>'phone','[^0-9]','','g'),10))) then raise exception 'Duplicate requires individual review: %',r->>'name'; end if;
 insert into public.businesses(name,category,city,address,phone,website,description,status,verified,claimed,rating,review_count,source,source_url,verification_source,verified_at) values(r->>'name',r->>'category',r->>'city',r->>'address',r->>'phone',r->>'website',r->>'description','approved',true,false,null,0,'editorial_first_party',r->>'source_url','first_party_website_desk_check',now()) returning id into bid;
 insert into public.listing_checks(business_id,source_url,checked_fields,service_areas,service_tags,scope_note) values(bid,r->>'source_url',array['identity','public contact route','website','advertised services','explicit service cities','service limits'],array(select jsonb_array_elements_text(r->'areas')),array(select jsonb_array_elements_text(r->'tags')),r->>'note');
 select to_jsonb(b) into applied from public.businesses b where id=bid;
 insert into directory_private.listing_corrections(business_id,previous_values,applied_values,reason,source_reference) values(bid,'{}'::jsonb,applied||jsonb_build_object('service_areas',r->'areas','service_tags',r->'tags','scope_note',r->>'note'),'Individually source-checked directory expansion; no seed publication',r->>'source_url');
end loop;end $curate$;
commit;
select b.id,b.name,b.city,b.verified_at,c.service_areas,c.service_tags,c.checked_at from public.businesses b join public.listing_checks c on c.business_id=b.id where b.website in ('https://www.mantecacrittersitters.com/','https://www.tylerspetboarding.com/');
